//! Public-facade conformance for nondurable activity event delivery.

use std::collections::VecDeque;
use std::fs;
use std::future::Future;
use std::path::{Path, PathBuf};
use std::pin::pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};

use gantry::event::{EventDraft, EventEnvelope, EventPayload, ProtectedReference};
use gantry::host::contracts::{
    FreshIdentityAllocator, HostError, HostFuture, IdentitySource, UtcClock,
};
use gantry::host::event::{
    EventDeliveryRequest, EventDeliveryRuntime, EventRetryPolicy, EventSink, ProtectedPayload,
    RedactionCapabilities, SinkDeliveryPolicy, SinkId,
};
use gantry::identity::ProtocolIdentity;
use gantry::observe::{
    ActivityBarrier, DeliveryKernel, EventCompleter, SinkPlan, SinkRegistration, project_payloads,
};
use gantry::portable::{
    DeliveryOutcome, EventKind, IdentityKind, JitterMode, ProtectedReferenceClass, SinkClass,
};
use gantry::timestamp::UtcTimestamp;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct ObservationVectors {
    format: String,
    event_completion: EventCompletionVector,
    projection_cases: Vec<ProjectionVector>,
    retry_cases: Vec<RetryVector>,
    barrier_cases: Vec<BarrierVector>,
}

#[derive(Debug, Deserialize)]
struct EventCompletionVector {
    kind: String,
    layer: String,
    activity_material: String,
    event_material: String,
    timestamp: String,
}

#[derive(Debug, Deserialize)]
struct ProjectionVector {
    class: String,
    raw_output: bool,
    operation_request_content: bool,
    operation_result_content: bool,
    integration_diagnostics: bool,
    source_snippets: bool,
    expected: String,
}

#[derive(Debug, Deserialize)]
struct RetryVector {
    initial_delay_us: u64,
    cap_us: u64,
    retry_number: u64,
    expected_ceiling_us: u64,
}

#[derive(Debug, Deserialize)]
struct BarrierVector {
    class: String,
    outcome: String,
    expected_barrier: String,
}

struct ScriptedIdentitySource(Mutex<VecDeque<Result<[u8; 32], HostError>>>);

impl ScriptedIdentitySource {
    fn new(responses: impl IntoIterator<Item = Result<[u8; 32], HostError>>) -> Self {
        Self(Mutex::new(responses.into_iter().collect()))
    }
}

impl IdentitySource for ScriptedIdentitySource {
    fn fresh_material(&self, _kind: IdentityKind) -> Result<[u8; 32], HostError> {
        self.0
            .lock()
            .map_err(|_| failure("identity-state"))?
            .pop_front()
            .unwrap_or_else(|| Err(failure("identity-exhausted")))
    }
}

struct FixedClock(UtcTimestamp);

impl UtcClock for FixedClock {
    fn utc_now<'a>(&'a self) -> HostFuture<'a, Result<UtcTimestamp, HostError>> {
        Box::pin(async move { Ok(self.0.clone()) })
    }
}

struct FixedSink(DeliveryOutcome);

impl EventSink for FixedSink {
    fn deliver<'a>(
        &'a self,
        _request: EventDeliveryRequest,
    ) -> HostFuture<'a, Result<DeliveryOutcome, HostError>> {
        Box::pin(async move { Ok(self.0) })
    }
}

struct ImmediateRuntime;

impl EventDeliveryRuntime for ImmediateRuntime {
    fn deliver_with_timeout<'a>(
        &'a self,
        sink: &'a dyn EventSink,
        request: EventDeliveryRequest,
        _timeout_us: u64,
    ) -> HostFuture<'a, Result<DeliveryOutcome, HostError>> {
        sink.deliver(request)
    }

    fn sleep<'a>(&'a self, _delay_us: u64) -> HostFuture<'a, Result<(), HostError>> {
        Box::pin(async { Ok(()) })
    }

    fn sample_full_jitter(&self, ceiling_us: u64) -> Result<u64, HostError> {
        Ok(ceiling_us)
    }
}

#[test]
fn canonical_event_completion_uses_public_occurrence_contracts() {
    let vectors = vectors();
    assert_eq!(vectors.format, "gantry.activity-observation-vectors/v1");
    let schema: serde_json::Value =
        read_json(&protocol_root().join("schemas/activity-observation-v1.schema.json"));
    assert_eq!(
        schema["$id"],
        "https://gantry.invalid/protocol/activity-observation/v1/schema.json"
    );

    let vector = vectors.event_completion;
    let kind = EventKind::from_wire_name(&vector.kind);
    assert!(kind.is_some());
    let kind = kind.unwrap_or_else(|| unreachable!("checked above"));
    assert_eq!(kind.layer().wire_name(), vector.layer);
    let timestamp = UtcTimestamp::from_unix_seconds(0, 42);
    assert!(timestamp.is_ok());
    let timestamp = timestamp.unwrap_or_else(|_| unreachable!("checked above"));
    assert_eq!(timestamp.to_string(), vector.timestamp);

    let source = ScriptedIdentitySource::new([decode_material(&vector.event_material)]);
    let allocator = FreshIdentityAllocator::default();
    let clock = FixedClock(timestamp.clone());
    let completer = EventCompleter::new(&allocator, &source, &clock);
    let activity = fresh(IdentityKind::Activity, &vector.activity_material);
    let completed = block_on(completer.complete(activity, EventDraft::new(kind, payload(b"{}"))));
    assert!(completed.is_ok());
    let completed = completed.unwrap_or_else(|_| unreachable!("checked above"));
    assert_eq!(completed.activity_id(), activity);
    assert_eq!(
        completed.event_id().to_string(),
        format!("event:{}", vector.event_material)
    );
    assert_eq!(completed.timestamp(), &timestamp);
}

#[test]
fn canonical_projection_and_retry_vectors_match_the_public_kernel() {
    let vectors = vectors();
    for (index, vector) in vectors.projection_cases.into_iter().enumerate() {
        let class = ProtectedReferenceClass::from_wire_name(&vector.class);
        assert!(class.is_some());
        let class = class.unwrap_or_else(|| unreachable!("checked above"));
        let reference = ProtectedReference::new(format!("payload-{index}"), class);
        assert!(reference.is_ok());
        let reference = reference.unwrap_or_else(|_| unreachable!("checked above"));
        let draft = EventDraft::new(EventKind::OperationCompletion, payload(b"{}"))
            .with_protected_references(vec![reference.clone()]);
        assert!(draft.is_ok());
        let event = complete(draft.unwrap_or_else(|_| unreachable!("checked above")));
        let policy = policy(
            SinkClass::Required,
            vector.raw_output,
            RedactionCapabilities {
                operation_request_content: vector.operation_request_content,
                operation_result_content: vector.operation_result_content,
                integration_diagnostics: vector.integration_diagnostics,
                source_snippets: vector.source_snippets,
            },
        );
        let projected = project_payloads(
            &event,
            &[ProtectedPayload {
                reference,
                bytes: Arc::from(&b"protected"[..]),
            }],
            &policy,
        );
        assert!(projected.is_ok());
        let projected = projected.unwrap_or_else(|_| unreachable!("checked above"));
        assert_eq!(projected.payloads().len(), 1);
        assert_eq!(
            projected.payloads()[0].projection.wire_name(),
            vector.expected
        );
        assert_eq!(
            projected.payloads()[0].bytes.is_some(),
            vector.expected == "available"
        );
    }

    for vector in vectors.retry_cases {
        let retry = EventRetryPolicy::new(
            "fixture",
            i64::MAX as u64,
            vector.initial_delay_us,
            vector.cap_us,
            JitterMode::None,
        );
        assert!(retry.is_ok());
        assert_eq!(
            gantry::observe::retry::delay_ceiling(
                &retry.unwrap_or_else(|_| unreachable!("checked above")),
                vector.retry_number,
            ),
            Some(vector.expected_ceiling_us)
        );
    }
}

#[test]
fn canonical_barrier_vectors_keep_required_failure_activity_scoped() {
    let vectors = vectors();
    for (index, vector) in vectors.barrier_cases.into_iter().enumerate() {
        let class = SinkClass::from_wire_name(&vector.class);
        let outcome = DeliveryOutcome::from_wire_name(&vector.outcome);
        assert!(class.is_some() && outcome.is_some());
        let class = class.unwrap_or_else(|| unreachable!("checked above"));
        let sink = Arc::new(FixedSink(
            outcome.unwrap_or_else(|| unreachable!("checked above")),
        ));
        let plan = SinkPlan::new(vec![SinkRegistration::new(
            sink_id(&format!("sink-{index}")),
            policy(class, false, RedactionCapabilities::default()),
            sink,
        )]);
        assert!(plan.is_ok());
        let allocator = FreshIdentityAllocator::default();
        let source = ScriptedIdentitySource::new([Ok([index as u8 + 30; 32])]);
        let kernel = DeliveryKernel::new(&allocator, &source, &ImmediateRuntime);
        let result = block_on(kernel.deliver(
            complete(EventDraft::new(EventKind::Parse, payload(b"{}"))),
            &[],
            &plan.unwrap_or_else(|_| unreachable!("checked above")),
        ));
        assert!(result.is_ok());
        let result = result.unwrap_or_else(|_| unreachable!("checked above"));
        let actual = match result.barrier {
            ActivityBarrier::Delivered => "delivered",
            ActivityBarrier::RequiredExhausted { .. } => "required-exhausted",
        };
        assert_eq!(actual, vector.expected_barrier);
    }
}

fn policy(
    class: SinkClass,
    raw_output: bool,
    capabilities: RedactionCapabilities,
) -> SinkDeliveryPolicy {
    let retry = EventRetryPolicy::new("retry-v1", 0, 0, 0, JitterMode::None);
    assert!(retry.is_ok());
    let policy = SinkDeliveryPolicy::new(
        class,
        raw_output,
        "redaction-v1",
        capabilities,
        retry.unwrap_or_else(|_| unreachable!("checked above")),
        30,
    );
    assert!(policy.is_ok());
    policy.unwrap_or_else(|_| unreachable!("checked above"))
}

fn complete(draft: EventDraft) -> EventEnvelope {
    let event = EventEnvelope::complete(
        fresh(IdentityKind::Event, &"11".repeat(32)),
        fresh(IdentityKind::Activity, &"22".repeat(32)),
        UtcTimestamp::from_unix_seconds(0, 42)
            .unwrap_or_else(|_| unreachable!("fixture timestamp is valid")),
        draft,
    );
    assert!(event.is_ok());
    event.unwrap_or_else(|_| unreachable!("checked above"))
}

fn payload(bytes: &[u8]) -> EventPayload {
    EventPayload::from_validated_canonical_bytes(Arc::<[u8]>::from(bytes))
        .unwrap_or_else(|_| unreachable!("fixture payload is nonempty"))
}

fn sink_id(value: &str) -> SinkId {
    SinkId::new(value).unwrap_or_else(|_| unreachable!("fixture sink ID is nonempty"))
}

fn fresh(kind: IdentityKind, hexadecimal: &str) -> ProtocolIdentity {
    ProtocolIdentity::from_fresh_material(
        kind,
        decode_material(hexadecimal).unwrap_or_else(|_| unreachable!("fixture material is valid")),
    )
    .unwrap_or_else(|_| unreachable!("fixture kind accepts fresh material"))
}

fn decode_material(value: &str) -> Result<[u8; 32], HostError> {
    if value.len() != 64 {
        return Err(failure("invalid-material"));
    }
    let mut material = [0_u8; 32];
    for (index, pair) in value.as_bytes().as_chunks::<2>().0.iter().enumerate() {
        let text = std::str::from_utf8(pair).map_err(|_| failure("invalid-material"))?;
        material[index] = u8::from_str_radix(text, 16).map_err(|_| failure("invalid-material"))?;
    }
    Ok(material)
}

fn failure(code: &'static str) -> HostError {
    HostError {
        code: Arc::from(code),
        protected_diagnostic: None,
    }
}

fn vectors() -> ObservationVectors {
    read_json(&protocol_root().join("goldens/activity-observation-vectors-v1.json"))
}

fn protocol_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../protocol")
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes = fs::read(path);
    assert!(bytes.is_ok(), "could not read {}", path.display());
    let value =
        bytes.and_then(|bytes| serde_json::from_slice(&bytes).map_err(std::io::Error::other));
    assert!(value.is_ok(), "could not decode {}", path.display());
    value.unwrap_or_else(|_| unreachable!("checked above"))
}

fn block_on<F: Future>(future: F) -> F::Output {
    let waker = Waker::noop();
    let mut context = Context::from_waker(waker);
    let mut future = pin!(future);
    match future.as_mut().poll(&mut context) {
        Poll::Ready(value) => value,
        Poll::Pending => panic!("deterministic observation future unexpectedly remained pending"),
    }
}

//! Independent validation of the analyzer profile evidence index.

use std::collections::BTreeSet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde::Deserialize;
use sha2::{Digest, Sha256};

const MANIFEST_PATH: &str = "protocol/conformance/generics-traits-analyzer-gate-v1.json";
const PREREQUISITES: [&str; 6] = [
    "GNT-GEN-AN-001",
    "GNT-GEN-AN-002",
    "GNT-GEN-AN-003",
    "GNT-GEN-AN-004",
    "GNT-GEN-API-001",
    "GNT-GEN-PROOF-001",
];
const REQUIRED_ARTIFACTS: [&str; 33] = [
    "crates/gantry-analysis/src/bodies.rs",
    "crates/gantry-analysis/src/effects.rs",
    "crates/gantry-analysis/src/generics.rs",
    "crates/gantry-analysis/src/lowering.rs",
    "crates/gantry-analysis/src/schemas.rs",
    "crates/gantry-analysis/src/types.rs",
    "crates/gantry-conformance/tests/analyzer_gate.rs",
    "crates/gantry-conformance/tests/analyzer_lowering.rs",
    "crates/gantry-conformance/tests/analyzer_types.rs",
    "crates/gantry-conformance/tests/analyzer_validity_model.rs",
    "crates/gantry-conformance/tests/external_facade_matrix.rs",
    "crates/gantry-conformance/tests/frontend_lexical_evidence.rs",
    "crates/gantry-conformance/tests/frontend_parser_evidence.rs",
    "crates/gantry-conformance/tests/ir_contracts.rs",
    "crates/gantry-conformance/tests/requirements_ledger.rs",
    "crates/gantry-conformance/tests/validate_package.rs",
    "crates/gantry/src/lib.rs",
    "crates/gantry/src/validate.rs",
    "docs/analyzer-generics-and-traits.md",
    "docs/analyzer-package-validity.md",
    "protocol/catalogs/ir-contracts-v1.json",
    "protocol/catalogs/profiles-v1.json",
    "protocol/conformance/analyzer-validity-v1.json",
    "protocol/conformance/generics-traits-frontend-v1.json",
    "protocol/conformance/generics-traits-ir-v1.json",
    "protocol/goldens/analyzer-validity-model-v1.json",
    "protocol/requirements/generated/requirements-v1.json",
    "protocol/requirements/reviewed-v1.json",
    "protocol/requirements/section14-v1.json",
    "protocol/schemas/canonical-ir-v1.schema.json",
    "protocol/schemas/generated-schema-object-v1.schema.json",
    "protocol/schemas/package-source-manifest-v1.schema.json",
    "protocol/schemas/source-map-v1.schema.json",
];

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Manifest {
    format: String,
    gate: String,
    status: String,
    specification: FileDigest,
    profile: String,
    prerequisites: Vec<Prerequisite>,
    artifacts: Vec<FileDigest>,
    review_summary: ReviewSummary,
    section14_excerpt_count: usize,
    claim: Claim,
    validation_commands: Vec<String>,
    environment_gaps: Vec<String>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct FileDigest {
    path: String,
    sha256: String,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Prerequisite {
    issue: String,
    commit: String,
    subject: String,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ReviewSummary {
    applicable_clause_count: usize,
    covered_count: usize,
    not_applicable_count: usize,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct Claim {
    profiles: Vec<String>,
    advertises_profiles: Vec<String>,
    excludes_profiles: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct RequirementReview {
    specification_sha256: String,
    requirements: Vec<Requirement>,
}

#[derive(Debug, Deserialize)]
struct Requirement {
    id: String,
    clauses: Vec<Clause>,
}

#[derive(Debug, Deserialize)]
struct Clause {
    key: String,
    profiles: Vec<String>,
    profile_reviews: Vec<ProfileReview>,
}

#[derive(Debug, Deserialize)]
struct ProfileReview {
    profile: String,
    state: String,
    evidence: Vec<String>,
    rationale: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Section14Review {
    specification_sha256: String,
    excerpts: Vec<Section14Excerpt>,
}

#[derive(Debug, Deserialize)]
struct Section14Excerpt {
    state: String,
    evidence: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ValidityManifest {
    specification_sha256: String,
    issue: String,
    profile: String,
    argument: String,
    model: String,
    evidence_manifests: Vec<String>,
    lemmas: Vec<serde_json::Value>,
}

#[test]
fn checked_in_analyzer_profile_gate_is_current() {
    let root = workspace_root();
    let manifest: Manifest = read_json(&root.join(MANIFEST_PATH));
    assert!(gantry::advertises_any_profile());
    assert_eq!(
        manifest.specification.sha256,
        gantry::PROFILE_SPECIFICATION_REVISION
    );
    assert_eq!(validate_manifest(&root, &manifest), Ok(()));
}

#[test]
fn analyzer_profile_gate_rejects_stale_artifacts_and_overclaiming() {
    let root = workspace_root();
    let manifest: Manifest = read_json(&root.join(MANIFEST_PATH));

    let mut stale = manifest.clone();
    stale.artifacts[0].sha256 = "0".repeat(64);
    assert!(validate_manifest(&root, &stale).is_err());

    let mut overclaim = manifest.clone();
    overclaim
        .claim
        .advertises_profiles
        .push("analyzer".to_owned());
    assert!(validate_manifest(&root, &overclaim).is_err());

    let mut incomplete = manifest;
    incomplete.prerequisites.pop();
    assert!(validate_manifest(&root, &incomplete).is_err());
}

fn validate_manifest(root: &Path, manifest: &Manifest) -> Result<(), String> {
    if manifest.format != "gantry.analyzer-gate-evidence/v1"
        || manifest.gate != "GNT-GEN-GATE-300"
        || manifest.status != "verified"
        || manifest.profile != "analyzer"
    {
        return Err("analyzer gate identity or status is invalid".to_owned());
    }
    if manifest.claim.profiles != ["analyzer", "frontend"]
        || manifest.claim.advertises_profiles != manifest.claim.profiles
        || manifest.claim.excludes_profiles
            != [
                "concurrent-evaluator",
                "durable-runtime",
                "embedding",
                "evaluator",
            ]
        || !gantry::PROFILE_CLAIMS_ENABLED
        || !gantry::advertises_any_profile()
    {
        return Err("analyzer claim is invalid or overstates a later profile".to_owned());
    }

    validate_file_digest(root, &manifest.specification, "specification")?;
    if manifest
        .prerequisites
        .iter()
        .map(|prerequisite| prerequisite.issue.as_str())
        .collect::<Vec<_>>()
        != PREREQUISITES
    {
        return Err("analyzer amendment prerequisites are incomplete".to_owned());
    }
    validate_sorted_unique(
        "prerequisite issues",
        manifest
            .prerequisites
            .iter()
            .map(|prerequisite| prerequisite.issue.as_str()),
    )?;
    for prerequisite in &manifest.prerequisites {
        validate_commit(root, prerequisite)?;
    }

    validate_sorted_unique(
        "artifact paths",
        manifest
            .artifacts
            .iter()
            .map(|artifact| artifact.path.as_str()),
    )?;
    if manifest
        .artifacts
        .iter()
        .map(|artifact| artifact.path.as_str())
        .collect::<Vec<_>>()
        != REQUIRED_ARTIFACTS
    {
        return Err("analyzer amendment artifact set is incomplete".to_owned());
    }
    for artifact in &manifest.artifacts {
        validate_file_digest(root, artifact, "artifact")?;
    }

    let review: RequirementReview = read_json(&root.join("protocol/requirements/reviewed-v1.json"));
    let section14: Section14Review =
        read_json(&root.join("protocol/requirements/section14-v1.json"));
    if review.specification_sha256 != manifest.specification.sha256
        || section14.specification_sha256 != manifest.specification.sha256
    {
        return Err("analyzer evidence uses another specification revision".to_owned());
    }

    let mut applicable_clause_count = 0_usize;
    let mut covered_count = 0_usize;
    let mut not_applicable_count = 0_usize;
    for requirement in &review.requirements {
        for clause in &requirement.clauses {
            if !clause.profiles.iter().any(|profile| profile == "analyzer") {
                continue;
            }
            applicable_clause_count += 1;
            let profile_review = clause
                .profile_reviews
                .iter()
                .find(|profile_review| profile_review.profile == "analyzer")
                .ok_or_else(|| {
                    format!(
                        "analyzer review is missing: {}:{}",
                        requirement.id, clause.key
                    )
                })?;
            match profile_review.state.as_str() {
                "covered" if !profile_review.evidence.is_empty() => {
                    covered_count += 1;
                    for evidence in &profile_review.evidence {
                        validate_evidence_anchor(root, evidence)?;
                    }
                }
                "not-applicable"
                    if profile_review.evidence.is_empty()
                        && profile_review
                            .rationale
                            .as_deref()
                            .is_some_and(|rationale| !rationale.is_empty()) =>
                {
                    not_applicable_count += 1;
                }
                _ => {
                    return Err(format!(
                        "analyzer review is not closed: {}:{}",
                        requirement.id, clause.key
                    ));
                }
            }
        }
    }
    if manifest.review_summary.applicable_clause_count != applicable_clause_count
        || manifest.review_summary.covered_count != covered_count
        || manifest.review_summary.not_applicable_count != not_applicable_count
        || applicable_clause_count != covered_count + not_applicable_count
    {
        return Err("analyzer review summary differs from reviewed applicability".to_owned());
    }

    if manifest.section14_excerpt_count != section14.excerpts.len()
        || section14
            .excerpts
            .iter()
            .any(|excerpt| excerpt.state != "covered" || excerpt.evidence.is_empty())
    {
        return Err("Section 14 authoring evidence is incomplete".to_owned());
    }

    let validity: ValidityManifest =
        read_json(&root.join("protocol/conformance/analyzer-validity-v1.json"));
    if validity.specification_sha256 != manifest.specification.sha256
        || validity.issue != "GNT-GEN-PROOF-001"
        || validity.profile != "analyzer"
        || !root.join(&validity.argument).is_file()
        || !root.join(&validity.model).is_file()
        || validity.evidence_manifests.len() != 6
        || validity.lemmas.len() != 9
        || validity
            .evidence_manifests
            .iter()
            .any(|path| !root.join(path).is_file())
    {
        return Err("analyzer validity evidence is incomplete".to_owned());
    }
    validate_sorted_unique(
        "validation commands",
        manifest.validation_commands.iter().map(String::as_str),
    )?;
    if manifest.environment_gaps
        != [
            "The analyzer and frontend claims are qualified on the recorded Linux cells; hosted macOS qualification is not claimed by this evidence gate.",
        ]
    {
        return Err("validation commands or environment gaps are incomplete".to_owned());
    }
    Ok(())
}

fn validate_evidence_anchor(root: &Path, evidence: &str) -> Result<(), String> {
    let (path, test) = evidence
        .split_once('#')
        .ok_or_else(|| format!("evidence anchor has no test: {evidence}"))?;
    if !path.starts_with("crates/gantry-conformance/tests/") || !path.ends_with(".rs") {
        return Err(format!(
            "evidence is not a public conformance test: {evidence}"
        ));
    }
    let source = fs::read_to_string(root.join(path))
        .map_err(|error| format!("could not read evidence {path}: {error}"))?;
    if !source.contains(&format!("fn {test}(")) {
        return Err(format!("evidence test is missing: {evidence}"));
    }
    Ok(())
}

fn validate_file_digest(root: &Path, file: &FileDigest, kind: &str) -> Result<(), String> {
    let bytes = fs::read(root.join(&file.path))
        .map_err(|error| format!("could not read {kind} {}: {error}", file.path))?;
    let actual = format!("{:x}", Sha256::digest(bytes));
    if actual != file.sha256 {
        return Err(format!("{kind} digest differs: {}", file.path));
    }
    Ok(())
}

fn validate_commit(root: &Path, prerequisite: &Prerequisite) -> Result<(), String> {
    let ancestor = Command::new("git")
        .current_dir(root)
        .args(["merge-base", "--is-ancestor", &prerequisite.commit, "HEAD"])
        .status()
        .map_err(|error| format!("could not inspect prerequisite commit: {error}"))?;
    if !ancestor.success() {
        return Err(format!(
            "prerequisite commit is not an ancestor: {}",
            prerequisite.issue
        ));
    }
    let subject = Command::new("git")
        .current_dir(root)
        .args(["show", "-s", "--format=%s", &prerequisite.commit])
        .output()
        .map_err(|error| format!("could not read prerequisite subject: {error}"))?;
    let actual = String::from_utf8(subject.stdout)
        .map_err(|error| format!("prerequisite subject is not UTF-8: {error}"))?;
    if actual.trim_end() != prerequisite.subject {
        return Err(format!(
            "prerequisite subject differs: {}",
            prerequisite.issue
        ));
    }
    Ok(())
}

fn validate_sorted_unique<'a>(
    name: &str,
    values: impl IntoIterator<Item = &'a str>,
) -> Result<(), String> {
    let values = values.into_iter().collect::<Vec<_>>();
    let unique = values.iter().copied().collect::<BTreeSet<_>>();
    if values.windows(2).any(|pair| pair[0] >= pair[1]) || unique.len() != values.len() {
        return Err(format!("{name} are not sorted and unique"));
    }
    Ok(())
}

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| unreachable!("conformance crate has a workspace root"))
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let bytes = fs::read(path);
    assert!(bytes.is_ok(), "could not read {}", path.display());
    let value =
        bytes.and_then(|bytes| serde_json::from_slice(&bytes).map_err(std::io::Error::other));
    assert!(value.is_ok(), "could not decode {}", path.display());
    value.unwrap_or_else(|_| unreachable!("checked above"))
}

