    let parent = LogicalValue::structure(
        integer_envelope.canonical_string(),
        vec![(
            "value".to_owned(),
            LogicalValue::integer(
                gantry::numeric::GantryInt::new(1)
                    .unwrap_or_else(|| unreachable!("fixture integer is in range")),
            ),
        )],
