            &workflow,
            "frame:0",
            "running",
            None,
        )
        .unwrap_or_else(|error| panic!("workflow-start failed: {error:?}")),
        workflow_event(
            WorkflowEventPhaseV1::End,
            &workflow,
            "frame:0",
            "succeeded",
