    let failure = MachineFailure {
        code: RuntimeCode::OperationBudget,
        workflow,
        site: StructuralPosition::new(vec![9])
            .unwrap_or_else(|error| panic!("failure site failed: {error}")),
    };
    for label in [
        MachineLabel::Cancellation {
            reason: Arc::from("caller"),
