        16 * 1_024 * 1_024,
        ValueLimits::new(256, 1_048_576, 1_048_576, 65_536)
            .unwrap_or_else(|| unreachable!("fixture value limits are positive")),
        10_000_000,
        100_000,
        1_000_000,
