            identity.clone(),
            CanonicalSignature::concrete_function(&identity, &[], &TypeDescriptor::UNIT),
            gantry::ir::EffectSet::default(),
            Vec::new(),
            vec![prompt],
            vec![task_sites[1].clone(), task_sites[0].clone()],
