    );
    transcript
        .append(&turn("hello"), DEFAULT_VALUE_LIMITS)
        .unwrap_or_else(|error| panic!("transcript append failed: {error:?}"));
    assert_canonical(transcript.bytes());
    assert_contains(
        transcript.bytes(),
        &[
            "\"operation_kind\":\"prompt\"",
            "\"selected_agent\":\"worker\"",
