fn configuration(services: Arc<Services>) -> InterpreterConfiguration {
    let required = RequiredConfiguration::new(
        FrontendLimits::new(
            8, 1_024, 4_096, 1_024, 32, 4_096, 4_096, 4_096, 4_096, 64, 1_024, 4_096,
        )
