const NEGATIVE_PATH: &str = "protocol/goldens/public-formats-v1.negatives.json";

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct FormatCatalog {
    catalog: String,
    major: u64,
    minor: u64,
    specification_revision: String,
