}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeCatalog {
    format: String,
    cases: Vec<NegativeFixture>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NegativeFixture {
