impl ModelState {
    const fn initial(value_type: ValueType) -> Self {
        Self {
            phase: InterpreterPhase::Running,
            task: TaskStatus::Running,
            operation: OperationStatus::Absent,
            value_type,
            generic_descriptor_closed: true,
            concrete_call_target_selected: true,
            concrete_effect_and_schema_selected: true,
            runtime_generic_analysis_steps: 0,
            remaining_source_steps: 1,
            accepted_results: 0,
            cancelled: false,
            source_steps_at_cancellation: None,
            accepted_results_at_cancellation: None,
            foreground: None,
            terminal: None,
            required_barrier_failed: false,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Action {
    AdmitNewWork,
    BarrierFail,
