    "linear-task-ownership",
    "concrete-effects-and-purity",
    "concrete-schema-closure",
    "diagnostic-precedence-and-witnesses",
    "closed-lowering-preservation",
    "bounded-artifact-admission"
  ],
  "assumptions": [
    "The package snapshot is immutable, completely selected, and syntax-valid.",
    "Protocol versions and the specification digest are the reviewed Gantry v1 values.",
    "The Boolean model abstracts finite implementation judgments and is not an enumeration of all source programs.",
    "Capture-avoiding substitution, unification, coherence, and lowering are justified by the written argument and property evidence rather than by the finite Boolean search."
  ],
  "counterexamples": [
    {
      "id": "artifact-limit",
      "source": "fn main() {}",
      "outcome": "operational-failure",
      "expected_code": "canonical-ir-byte-limit"
    },
    {
      "id": "binder-well-formedness",
      "source": "fn keep<T,T>(value: T) -> T { value } fn main() {}",
      "outcome": "source-invalid",
      "expected_code": "duplicate-type-parameter"
    },
    {
      "id": "effects-purity",
      "source": "pure fn main() { discard prompt \"x\" -> String; }",
      "outcome": "source-invalid",
      "expected_code": "impure-workflow"
    },
    {
      "id": "inference-completeness",
      "source": "fn empty<T>() {} fn main() { empty(); }",
      "outcome": "source-invalid",
      "expected_code": "incomplete-type-inference"
    },
    {
      "id": "linear-ownership",
      "source": "fn main() { spawn task { return; } }",
      "outcome": "source-invalid",
      "expected_code": "unconsumed-task-handle"
    },
    {
      "id": "module-resolution",
      "source": "mod absent;\nfn main() {}",
      "outcome": "source-invalid",
      "expected_code": "missing-module-source"
    },
    {
      "id": "monomorphization-finiteness",
      "source": "fn grow<T>() { grow::<List<T>>() } fn main() { grow::<String>() }",
      "outcome": "source-invalid",
      "expected_code": "polymorphic-recursion",
      "expected_field": "instantiation_witness"
    },
    {
      "id": "name-resolution",
      "source": "fn main() { missing_name; }",
      "outcome": "source-invalid",
      "expected_code": "unresolved-reference"
    },
    {
      "id": "structural-capability",
      "source": "struct Envelope<T> where T: Equatable { value: T } fn inspect(value: Envelope<Decision>) {} fn main() {}",
      "outcome": "source-invalid",
      "expected_code": "unsatisfied-bound",
      "expected_field": "capability"
    },
    {
      "id": "trait-coherence",
      "source": "trait Label { pure fn label(self) -> String; } struct Envelope<T> { value: T } impl<T> Label for Envelope<T> { pure fn label(self) -> String { \"generic\" } } impl Label for Envelope<String> { pure fn label(self) -> String { \"specific\" } } fn main() {}",
      "outcome": "source-invalid",
      "expected_code": "overlapping-implementation"
    },
    {
      "id": "trait-obligation-cycle",
      "source": "trait First<T> { pure fn label(self) -> String; } trait Second<T> { pure fn second(self) -> String; } struct Item {} struct Envelope<T> { value: T } impl<T> First<T> for Envelope<T> where T: Second<Envelope<T>> { pure fn label(self) -> String { \"first\" } } impl<T> Second<T> for Item where T: First<Item> { pure fn second(self) -> String { \"second\" } } fn main(value: Envelope<Item>) -> String { First::<Item>::label(value) }",
      "outcome": "source-invalid",
      "expected_code": "cyclic-trait-obligation",
      "expected_field": "obligation_chain"
    },
    {
      "id": "type-completion",
      "source": "fn main(flag: Bool) -> Int { if flag { return 1; } }",
      "outcome": "source-invalid",
      "expected_code": "missing-result"
    }
  ],
