    "compact": "fn main() { discard prompt \"x\" -> String; }",
    "cosmetic": "// layout-only change\nfn main() {\n    discard prompt \"x\" -> String;\n}",
    "semantic": "fn main() { discard prompt \"y\" -> String; }"
  },
  "metamorphic_cases": [
    {
      "id": "alpha-renaming",
      "left": "fn keep<T>(value: T) -> T { value } fn main() { discard keep(1); }",
      "right": "fn keep<U>(value: U) -> U { value } fn main() { discard keep(1); }"
    },
    {
      "id": "implementation-order",
      "left": "trait Label { pure fn label(self) -> String; } struct First {} struct Second {} impl Label for First { pure fn label(self) -> String { \"first\" } } impl Label for Second { pure fn label(self) -> String { \"second\" } } fn main() {}",
      "right": "trait Label { pure fn label(self) -> String; } struct First {} struct Second {} impl Label for Second { pure fn label(self) -> String { \"second\" } } impl Label for First { pure fn label(self) -> String { \"first\" } } fn main() {}"
    },
    {
      "id": "predicate-order",
      "left": "trait First { pure fn first(self); } trait Second { pure fn second(self); } struct Item {} impl First for Item { pure fn first(self) {} } impl Second for Item { pure fn second(self) {} } fn inspect<T>(value: T) where T: First, T: Second { value.first(); value.second(); } fn main(value: Item) { inspect(value); }",
      "right": "trait First { pure fn first(self); } trait Second { pure fn second(self); } struct Item {} impl First for Item { pure fn first(self) {} } impl Second for Item { pure fn second(self) {} } fn inspect<T>(value: T) where T: Second, T: First { value.first(); value.second(); } fn main(value: Item) { inspect(value); }"
    }
  ]
